import{_ as r,l,o as e,c as n,v as t,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"同态加密直觉","description":"","frontmatter":{"title":"同态加密直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/homomorphic-intuition.md","filePath":"cs/homomorphic-intuition.md","lastUpdated":1789023840000}'),c={name:"cs/homomorphic-intuition.md"};function m(u,a,E,_,A,f){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="同态加密直觉" tabindex="-1">同态加密直觉 <a class="header-anchor" href="#同态加密直觉" aria-label="Permalink to &quot;同态加密直觉&quot;">​</a></h1><div class="epigraph"><p>同态让未打开的密文还能加或乘，解密后等于对明文做了同样的运算。半同态已能做选举与简单统计；全同态能评任意电路，代价是噪声与参数。</p><footer>—— Rivest, Adleman and Dertouzos 的设想；Paillier；Gentry, Fully Homomorphic Encryption Using Ideal Lattices, STOC 2009</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/threshold-mpc">MPC</a>靠交互。缺口是<strong>非交互外包</strong>：数据在服务器上以密文计算，服务器不该见明文。本课直觉，不把 FHE 写成已可替换数据库的产品课。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AEAD 密文不能加。RSA 的乘性是缺陷也是半同态；Paillier 加同态更常用。Gentry：自举刷新噪声，使任意深度电路成为可能。缺口是噪声、电路深度与「谁持私钥仍见结果」——服务器无私钥则只见密文。</p><h3 id="结果给谁看" tabindex="-1">结果给谁看 <a class="header-anchor" href="#结果给谁看" aria-label="Permalink to &quot;结果给谁看&quot;">​</a></h3><p>同态不解决访问控制：能解密的人看见 \\(f(x)\\)。要隐藏 \\(f(x)\\) 仍需 MPC 或只把结果给客户。</p><p><span class="marginnote">Gentry 2009。后续 BGV/BFV/CKKS 是工程族，本课不选厂商。不要发明 arXiv 号。CKKS 近似算术有精度合同，不是精确整数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分三级：部分（一种运算）、有限深度、全同态。对照 MPC：通信轮次 vs 密文膨胀。指出引导（bootstrapping）是噪声管理，不是「再加密一次」的口号。</p>',12)),(e(),s(p,null,{default:i(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%98%8E%E6%96%87%22%5D%20--%3E%20ENC%5B%22%E5%8A%A0%E5%AF%86%22%5D%0A%20%20ENC%20--%3E%20EVAL%5B%22%E5%AF%B9%E5%AF%86%E6%96%87%E8%AF%84%E7%94%B5%E8%B7%AF%22%5D%0A%20%20EVAL%20--%3E%20DEC%5B%22%E6%8C%81%E9%92%A5%E8%80%85%E8%A7%A3%E5%AF%86%E5%BE%97%20f(x)%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>外包计算的威胁模型：服务器诚实执行电路但好奇。恶意服务器可改电路，完整性要另验（或用验证计算）。可证明安全下一课把这些都收成归约语言。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写自举的格细节。下一课可证明安全与归约：把本单元的游戏语言收口，并通向误用清单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MPC 交互；同态把计算丢给持密文方。</li><li>半同态一种运算；FHE 任意电路加噪声管理。</li><li>解密者仍见结果；完整性另议。</li><li>下一课：可证明安全与归约。</li><li>出处：Gentry, 2009；Paillier；Rivest, Adleman and Dertouzos。</li></ul>',8))])}const x=r(c,[["render",m]]);export{b as __pageData,x as default};
